import type { Check } from './lessons';

export type Topic = 'html' | 'css' | 'js' | 'php' | 'sql';
export type PracticeTask = {
  id: string; topic: Exclude<Topic, 'sql'>; section: string; difficulty: number; title: string; prompt: string;
  explain: string; hint?: string; starter: Record<string, string>; solution: Record<string, string>; checks: Check[]; mode: 'web' | 'php';
};

// ---------------- pomocnicze ----------------
const H = (body: string, head = '') => `<!DOCTYPE html>\n<html lang="pl">\n<head>\n  <meta charset="UTF-8">\n  <title>Ćwiczenie</title>\n${head}</head>\n<body>\n${body}\n</body>\n</html>\n`;
const CSSLINK = '  <link rel="stylesheet" href="styl.css">\n';
const JS = '\n  <script src="skrypt.js"></script>';
const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

type D = [string, number?, string?]; // selektor, min, tekst
const dom = (list: (string | D)[]): Check[] => list.map((x) => {
  const [selector, min, textIncludes] = typeof x === 'string' ? [x] : x;
  return { kind: 'dom', selector, min, textIncludes, label: `Jest: ${selector}${min && min > 1 ? ` (min. ${min})` : ''}${textIncludes ? ` z tekstem „${textIncludes}”` : ''}` };
});
/** CSS: [selektor, wlasciwosc, wartosc (regex)] -> sprawdzenie w styl.css */
const css = (list: [string, string, string][]): Check[] => list.map(([sel, prop, val]) => ({
  kind: 'regex', file: 'styl.css', flags: 'i',
  pattern: `(^|[}\\s,])${esc(sel)}\\s*(,[^{]*)?\\{[^}]*(^|[;{\\s])${prop}\\s*:\\s*${val}`,
  label: `${sel} { ${prop}: … }`,
}));
const re = (file: string, list: [string, string][]): Check[] => list.map(([pattern, label]) => ({ kind: 'regex', file, pattern, flags: 'is', label }));

type Def = { id: string; s: string; d: number; t: string; p: string; e: string; sol: Record<string, string>; checks: Check[]; start?: Record<string, string>; hint?: string };

