// CSS
// =====================================================================
const C = (body: string) => ({ 'index.html': H(body, CSSLINK) });
const cs = (id: string, s: string, d: number, t: string, p: string, e: string, html: string, style: string, rules: [string, string, string][], extra: Check[] = []): Def =>
  ({ id, s, d, t, p, e, sol: { ...C(html), 'styl.css': style }, start: { ...C(html), 'styl.css': '' }, checks: [...css(rules), ...extra] });

