// ---------------- zlozenie ----------------
function build(topic: PracticeTask['topic'], defs: Def[]): PracticeTask[] {
  return defs.map((d) => ({
    id: d.id, topic, section: d.s, difficulty: d.d, title: d.t, prompt: d.p, explain: d.e, hint: d.hint,
    starter: d.start ?? (topic === 'html' ? { 'index.html': H('  ') } : d.sol), solution: d.sol, checks: d.checks, mode: topic === 'php' ? 'php' : 'web',
  }));
}

export const PRACTICE: PracticeTask[] = [
  ...build('html', HTML_DEFS),
  ...build('css', CSS_DEFS),
  ...build('js', JS_DEFS),
  ...build('php', PHP_DEFS),
];

export const SECTIONS: Record<PracticeTask['topic'], string[]> = {
  html: Array.from(new Set(HTML_DEFS.map((d) => d.s))),
  css: Array.from(new Set(CSS_DEFS.map((d) => d.s))),
  js: Array.from(new Set(JS_DEFS.map((d) => d.s))),
  php: Array.from(new Set(PHP_DEFS.map((d) => d.s))),
};

